from ta_moler.cmd.egate.genericepcsim import GenericEPCSIMCommand
from moler.exceptions import ParsingDone, CommandFailure
import re


class Set(GenericEPCSIMCommand):
    """Command set."""

    def __init__(self, connection, params, prompt=None, newline_chars=None, runner=None):
        """
        Command set.

        :param connection: moler connection to device, terminal when command is executed
        :param prompt: expected prompt sending by device after command execution
        :param newline_chars: Characters to split lines
        :param runner: Runner to run command
        """
        super(Set, self).__init__(connection=connection, prompt=prompt, newline_chars=newline_chars,
                                  runner=runner)
        self.params = params
        self.current_ret["STATUS"] = "SUCCESS"

    def build_command_string(self):
        """
        Build command string from parameters passed to object.

        :return: String representation of command to send over connection to device.
        """
        cmd = f'set {self.params}'
        return cmd

    def on_new_line(self, line, is_full_line):
        """
        Put your parsing code here.

        :param line: Line to process, can be only part of line. New line chars are removed from line.
        :param is_full_line: True if line had new line chars, False otherwise
        :return: None
        """
        if is_full_line:
            try:
                self._parse_error(line)
            except ParsingDone:
                pass
        return super(Set, self).on_new_line(line, is_full_line)

    #
    _re_error = re.compile(r"(?P<ERROR>.+)")

    def _parse_error(self, line):
        if self._regex_helper.search_compiled(Set._re_error, line):
            self.set_exception(CommandFailure(self, self._regex_helper.group("ERROR")))
            raise ParsingDone


COMMAND_OUTPUT = """EGATE> set <params>
EGATE>"""

COMMAND_KWARGS = {
    "params": "<params>"
}

COMMAND_RESULT = {
    "STATUS": "SUCCESS"
}
